#include "../charge_compiler/json.hpp"
#include <array>
#include <cstdint>
#include <algorithm>
#include <limits>
#include <iostream>
#include <time.h>
using I=long long;
static double now(){timespec t{};require(clock_gettime(CLOCK_BOOTTIME,&t)==0,"clock");return t.tv_sec+t.tv_nsec*1e-9;}
static std::string_view token(std::string_view&s){size_t begin=s.find_first_not_of(" \t\r");if(begin==s.npos){s={};return{};}s.remove_prefix(begin);auto end=s.find_first_of(" \t\r");auto out=s.substr(0,end);if(end==s.npos)s={};else s.remove_prefix(end);return out;}
static double number(std::string_view t){require(!t.empty(),"waveform number required");double v;auto r=std::from_chars(t.data(),t.data()+t.size(),v);require(r.ec==std::errc{}&&r.ptr==t.data()+t.size()&&std::isfinite(v),"complete finite waveform number");return v;}
struct Cross {std::array<std::vector<double>,2> events;void add(double ta,double tb,double a,double b,double threshold){if(a<threshold&&threshold<=b)events[1].push_back(ta+(tb-ta)*(threshold-a)/(b-a));if(b<threshold&&threshold<=a)events[0].push_back(ta+(tb-ta)*(threshold-a)/(b-a));}};
struct Case{double initial_in=0,initial_out=0,previous_in=0,previous_out=0,minimum=std::numeric_limits<double>::infinity(),maximum=-std::numeric_limits<double>::infinity();Cross incoming;std::array<Cross,3> outgoing;};
static Json vector_ns(const std::vector<double>&v){Json result=Json::array();for(auto t:v)result.push(t*1e9);return result;}
int main(int argc,char**argv){try{
 require(argc==2,"usage CONFIG");auto cfg=Json::read(argv[1]);auto plan=Json::read(cfg.at("plan").str());auto&fixtures=plan.at("fixtures").arr();require(!fixtures.empty(),"nonempty fixtures");double deadline=cfg.at("deadline_uptime").num();std::vector<Case> cases(fixtures.size());std::ifstream input(cfg.at("waveform").str());require(bool(input),"waveform open");std::string line;require(bool(std::getline(input,line)),"waveform header");std::string_view rest=line;require(token(rest)=="Index"&&token(rest)=="TIME","waveform index/time columns");for(size_t i=0;i<cases.size();i++){require(token(rest)=="V(IN_"+std::to_string(i)+")"&&token(rest)=="V(OUT_"+std::to_string(i)+")","exact waveform signal columns");}require(token(rest).empty(),"waveform column count");uint64_t rows=0;bool terminal=false;double previous_time=0,last_time=0;const std::array<double,3> levels{.36,.9,1.44};
 while(std::getline(input,line)){if(rows%1000==0)require(now()<deadline,"waveform assessment deadline");if(line.find("End of Xyce(TM) Simulation")!=line.npos){require(!terminal,"unique native terminal marker");terminal=true;continue;}rest=line;auto index=token(rest);if(index.empty())continue;require(!terminal,"waveform data after terminal marker");uint64_t n;auto parsed=std::from_chars(index.data(),index.data()+index.size(),n);require(parsed.ec==std::errc{}&&parsed.ptr==index.data()+index.size()&&n==rows,"contiguous waveform row index");double t=number(token(rest));require(rows?t>previous_time:t==0,"strictly increasing waveform time");
 for(size_t i=0;i<cases.size();i++){double incoming=number(token(rest)),outgoing=number(token(rest));auto&c=cases[i];if(!rows){c.initial_in=incoming;c.initial_out=outgoing;}else{c.incoming.add(previous_time,t,c.previous_in,incoming,.9);for(size_t level=0;level<3;level++)c.outgoing[level].add(previous_time,t,c.previous_out,outgoing,levels[level]);}c.minimum=std::min(c.minimum,outgoing);c.maximum=std::max(c.maximum,outgoing);c.previous_in=incoming;c.previous_out=outgoing;}
 require(token(rest).empty(),"waveform row width");rows++;previous_time=t;last_time=t;}
 require(input.eof()&&terminal&&rows>1&&last_time>=34e-9-1e-15,"complete 34ns terminal waveform");Json records=Json::array();I passing=0,slew_passing=0;
 for(size_t i=0;i<cases.size();i++){auto&c=cases[i];bool inverted=fixtures[i].at("inverted").boolean();Json r=Json::object();r["case_index"]=I(i);r["output_min_v"]=c.minimum;r["output_max_v"]=c.maximum;bool passed=std::fabs(c.initial_in)<1e-6&&(inverted?c.initial_out>=1.62:c.initial_out<=.18)&&c.minimum<.18&&c.maximum>1.62;
 if(passed)for(int rising=0;rising<2;rising++){auto&starts=c.incoming.events[rising];auto&ends=c.outgoing[1].events[bool(rising)!=inverted];if(starts.size()!=2||ends.size()!=2){passed=false;break;}Json delays=Json::array();for(double t:starts){uint64_t count=0;double selected=0;for(double u:ends)if(t-1e-9<u&&u<t+5e-9){count++;selected=u;}if(count!=1){passed=false;break;}delays.push((selected-t)*1e9);}if(!passed)break;r[rising?"input_rise_delay_ns":"input_fall_delay_ns"]=delays;}
 r["passed"]=passed;if(!passed)r["reason"]="DC rail or propagation threshold/event correspondence failed";passing+=passed;bool strict=true;
 for(int rising=0;rising<2;rising++){auto&a=c.outgoing[rising?0:2].events[rising];auto&b=c.outgoing[1].events[rising];auto&d=c.outgoing[rising?2:0].events[rising];bool ordered=a.size()==2&&b.size()==2&&d.size()==2;if(ordered)for(size_t k=0;k<2;k++)ordered=ordered&&a[k]<b[k]&&b[k]<d[k];strict=strict&&ordered;if(ordered){Json slew=Json::array();for(size_t k=0;k<2;k++)slew.push((d[k]-a[k])*1e9);r[rising?"output_rise_slew_ns":"output_fall_slew_ns"]=slew;}}
 r["strict_output_slew_passed"]=strict;if(!strict){Json raw=Json::object();const std::array<const char*,3> labels{"0.36","0.9","1.44"};for(int rising=0;rising<2;rising++)for(size_t l=0;l<3;l++)raw[std::string(rising?"rise_":"fall_")+labels[l]]=vector_ns(c.outgoing[l].events[rising]);r["raw_output_threshold_crossings_ns"]=raw;}slew_passing+=strict;records.push(r);}
 Json result=Json::object();result["fixtures"]=I(cases.size());result["passing"]=passing;result["strict_output_slew_passing"]=slew_passing;result["records"]=records;result["waveform_rows"]=I(rows);result["all_native_waveform_events_terminal"]=true;std::ofstream output(cfg.at("report").str());output<<result.dump()<<'\n';require(bool(output),"compiled assessment report close");return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
